<script setup lang="ts">import {ref,onMounted,computed,watch} from 'vue';import {useRoute} from 'vue-router';import {useResearch} from '../stores/research';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import {features,shortNames} from '../constants/enums';import {number} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import EmptyState from '../components/common/EmptyState.vue';import ModelSummary from '../components/ModelSummary.vue';import PredictionPlot from '../components/PredictionPlot.vue';import ImportancePlot from '../components/ImportancePlot.vue';const route=useRoute(),lab=useResearch(),selected=ref(Number(route.query.run)||0),chosen=ref(0),{error,perform}=useTask();const run=computed(()=>lab.runs.find(r=>r.id===selected.value)),findings=computed(()=>lab.findings.filter(f=>f.run_id===selected.value)),finding=computed(()=>findings.value.find(f=>f.id===chosen.value)||findings.value[0]);onMounted(()=>perform(async()=>{await lab.load();if(!selected.value)selected.value=lab.runs[0]?.id||0;}));watch(()=>route.query.run,v=>{if(v)selected.value=Number(v);});usePolling(async()=>{if(run.value&&['queued','running'].includes(run.value.status))await lab.load();});</script><template><PageHeading index="04" title="在未见楼宇上，分开读表现与依赖" text="系数描述拟合关联；置换描述已拟合模型对某个特征的依赖，不推出改造因果收益。"><RouterLink class="outline" :to="'/hypotheses?finding='+finding?.id">记录改造假设 ↗</RouterLink></PageHeading><ErrorNotice :message="error" @retry="perform(lab.load)"/><div class="run-selector"><label>模型研究<select v-model="selected"><option v-for="r in lab.runs" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><StatusBadge v-if="run" :status="run.status"/></div><template v-if="run?.status==='completed'"><div class="evaluation-layout"><PredictionPlot :run="run"/><ModelSummary :run="run"/></div><div class="driver-layout"><ImportancePlot :findings="findings"/><section class="feature-reading"><label>读取特征<select :value="finding?.id" @change="chosen=Number(($event.target as HTMLSelectElement).value)"><option v-for="f in findings" :key="f.id" :value="f.id">{{features[f.feature]}}</option></select></label><template v-if="finding"><h2>{{shortNames[finding.feature]}}</h2><dl><div><dt>原单位系数</dt><dd>{{number(finding.coefficient,5)}}</dd></div><div><dt>每训练SD的系数 / kWh</dt><dd>{{number(finding.standardized_coefficient,3)}}</dd></div><div><dt>置换 ΔMAE均值 / kWh</dt><dd :class="{negative:finding.importance_mean<0}">{{number(finding.importance_mean,3)}}</dd></div><div><dt>重复分位范围</dt><dd>{{number(finding.importance_low,2)}} — {{number(finding.importance_high,2)}}</dd></div></dl><p>负ΔMAE表示本次打乱后误差更小，原样保留。重复范围不代表抽样置信覆盖，也不代表改变该特征会产生同等节能。</p><details><summary>查看全部{{finding.repeats.length}}次置换结果</summary><div class="repeat-values"><span v-for="(value,i) in finding.repeats" :key="i">{{i+1}} / {{number(value,4)}}</span></div></details></template></section></div><section class="split-evidence"><div class="section-heading"><h2>楼宇分组与标准化核验</h2><span>训练、验证、封存均以building分组</span></div><div class="split-labels"><p><b>最终训练</b>{{run.result.split?.train_buildings.join(' / ')}}</p><p><b>封存评估</b>{{run.result.split?.test_buildings.join(' / ')}}</p></div><div class="table-wrap"><table><thead><tr><th>折</th><th>折内训练楼宇</th><th>验证楼宇</th><th>训练行 / 验证行</th></tr></thead><tbody><tr v-for="f in run.result.folds" :key="f.fold"><td>{{f.fold}}</td><td>{{f.train_buildings.join(' / ')}}</td><td>{{f.validation_buildings.join(' / ')}}</td><td>{{f.train_row_ids.length}} / {{f.validation_row_ids.length}}</td></tr></tbody></table></div><details><summary>查看每折训练内尺度与行ID复算记录</summary><pre>{{JSON.stringify({split:run.result.split,folds:run.result.folds,final_scaler_mean:run.result.final_scaler_mean,final_fit_row_ids:run.result.final_fit_row_ids},null,2)}}</pre></details><p class="fingerprint">训练选择 SHA256 / {{run.result.selection_fingerprint}}</p><p class="fingerprint">完整输入 SHA256 / {{run.result.input_fingerprint}}</p></section></template><EmptyState v-else :title="run?.status==='failed'?'研究未完成':'先建立一份分组模型研究'" :text="run?.error||'在训练楼宇内完成比较并锁定模型后，才公开封存评估和置换解释。'"/></template>
